  /* =======================================================================
   * 标题翻译服务 (Google 免费接口 + 本地缓存)
   * ===================================================================== */
  async function translateText(text, fromLang, toLang) {
    if (!text || !text.trim()) return '';
    const src = text.trim();
    fromLang = fromLang || 'ja';
    toLang = toLang || 'zh-CN';
    const cacheKey = 'jhs_translate_v2';
    let cache = {};
    try { cache = JSON.parse(localStorage.getItem(cacheKey) || '{}'); } catch (e) {}
    if (cache[src]) return cache[src];

    let trans = '';
    try {
      const apiUrl = 'https://translate-pa.googleapis.com/v1/translate?' + new URLSearchParams({
        'params.client': 'gtx',
        dataTypes: 'TRANSLATION',
        key: 'AIzaSyDLEeFI5OtFBwYBIoK_jj5m32rZK5CkCXA',
        'query.sourceLanguage': fromLang,
        'query.targetLanguage': toLang,
        'query.text': src
      });
      const res = await gmHttp.get(apiUrl);
      const json = JSON.parse(res);
      trans = json && json.translation ? json.translation.trim() : '';
    } catch (e1) {
      try {
        const fallbackUrl = 'https://translate.googleapis.com/translate_a/single?client=gtx&sl=' +
          encodeURIComponent(fromLang) + '&tl=' + encodeURIComponent(toLang) + '&dt=t&q=' + encodeURIComponent(src);
        const res2 = await gmHttp.get(fallbackUrl);
        const json2 = JSON.parse(res2);
        if (json2 && json2[0] && json2[0][0] && json2[0][0][0]) trans = json2[0][0][0].trim();
      } catch (e2) {}
    }

    if (trans) {
      try {
        const keys = Object.keys(cache);
        if (keys.length > 500) {
          for (let i = 0; i < 100 && i < keys.length; i++) delete cache[keys[i]];
        }
        cache[src] = trans;
        localStorage.setItem(cacheKey, JSON.stringify(cache));
      } catch (e) {}
    }
    return trans;
  }

  /* =======================================================================
   * 女优信息与现役/退役检测服务 (jsDelivr CDN 自建库 + 维基百科回退 + 7天缓存)
   * ===================================================================== */
  const ActressService = {
    repoBase: 'https://cdn.jsdelivr.net/gh/lesspem/JAV_info@main/dist/',
    repoBaseFallback: 'https://raw.githubusercontent.com/lesspem/JAV_info/main/dist/',
    _idxMem: null,
    _shardMem: {},
    _cacheKey: 'jhs_actress_info_v2',

    getLocalCache: function () {
      try { return JSON.parse(localStorage.getItem(this._cacheKey) || '{}'); } catch (e) { return {}; }
    },
    saveLocalCache: function (cache) {
      try {
        if (cache && typeof cache === 'object') {
          const keys = Object.keys(cache);
          if (keys.length > 300) {
            for (let i = 0; i < 60 && i < keys.length; i++) delete cache[keys[i]];
          }
        }
        localStorage.setItem(this._cacheKey, JSON.stringify(cache));
      } catch (e) {}
    },

    getRepoIndex: async function () {
      if (this._idxMem) return this._idxMem;
      const ck = 'jhs_repo_index_cache';
      try {
        const raw = localStorage.getItem(ck);
        if (raw) {
          const o = JSON.parse(raw);
          if (o && o.t && Date.now() - o.t < 6048e5 && o.d) {
            this._idxMem = o.d;
            return o.d;
          }
        }
      } catch (e) {}

      let txt = '';
      for (const base of [this.repoBase, this.repoBaseFallback]) {
        try { txt = await gmHttp.get(base + 'index.json'); if (txt) break; } catch (e) {}
      }
      if (!txt) return null;
      try {
        const d = JSON.parse(txt);
        this._idxMem = d;
        try { localStorage.setItem(ck, JSON.stringify({ t: Date.now(), d: d })); } catch (e) {}
        return d;
      } catch (e) { return null; }
    },

    lookupRepo: async function (name) {
      if (!name) return null;
      const idx = await this.getRepoIndex();
      if (!idx) return null;
      const actors = idx.actors || {};
      const aliases = idx.aliases || {};

      // 原生别名拆分匹配，无需任何手工繁简字表
      const names = String(name).split(/[,，\/]/).map(s => s.trim()).filter(Boolean);
      if (!names.includes(name.trim())) names.unshift(name.trim());

      let key = null;
      for (const n of names) {
        if (actors.hasOwnProperty(n)) { key = n; break; }
        if (aliases.hasOwnProperty(n)) { key = aliases[n]; break; }
      }
      if (!key) return null;
      const sid = String(actors[key]).padStart(2, '0');
      let shard = this._shardMem[sid];
      if (!shard) {
        let txt = '';
        for (const base of [this.repoBase, this.repoBaseFallback]) {
          try { txt = await gmHttp.get(base + 'shard-' + sid + '.json'); if (txt) break; } catch (e) {}
        }
        if (!txt) return null;
        try { shard = JSON.parse(txt); this._shardMem[sid] = shard; } catch (e) { return null; }
      }
      const rec = shard[key];
      if (!rec) return null;
      const b = (rec.birth || '').trim();
      let birthday = '', age = '';
      const m = /^(\d{4})-(\d{2}|\?\?)-(\d{2}|\?\?)$/.exec(b);
      if (m) {
        birthday = b.replace(/-/g, '.');
        const y = parseInt(m[1], 10);
        if (!isNaN(y)) age = (new Date().getFullYear() - y) + '岁';
      }
      return {
        birthday: birthday,
        age: age,
        height: rec.height ? rec.height + 'cm' : '',
        weight: rec.weight ? rec.weight + 'kg' : '',
        threeSizeText: rec.bust && rec.waist && rec.hip ? (rec.bust + '-' + rec.waist + '-' + rec.hip) : '',
        braSize: rec.cup ? (rec.cup + '罩杯') : '',
        activeRaw: rec.active || '',
        retireRaw: rec.retire || '',
        bodyRetired: false,
        primaryKey: key,
        url: 'https://ja.wikipedia.org/wiki/' + encodeURIComponent(key)
      };
    },

    lookupWiki: async function (name) {
      if (!name) return null;
      let targetName = name;
      if (targetName === '三上悠亞') targetName = '三上悠亜';
      const wikiUrl = 'https://ja.wikipedia.org/wiki/' + encodeURIComponent(targetName);
      try {
        const html = await gmHttp.get(wikiUrl);
        const doc = new DOMParser().parseFromString(html, 'text/html');
        const pick = function (sel, fn) {
          try {
            const el = doc.querySelector(sel);
            return el ? fn(el).trim() : '';
          } catch (e) { return ''; }
        };
        const birthday = pick('a[title="誕生日"]', el => el.closest('tr') ? el.closest('tr').querySelector('td').textContent : '');
        const ageRaw = pick('th', el => el.textContent.includes('現年齢') ? el.parentNode.querySelector('td').textContent : '');
        const age = ageRaw && !isNaN(parseInt(ageRaw, 10)) ? (parseInt(ageRaw, 10) + '岁') : '';
        const heightRaw = pick('tr:has(a[title="身長"]) td', el => el.textContent);
        const height = heightRaw ? (heightRaw.split(' ')[0] + 'cm') : '';
        const activeRaw = pick('th', el => el.textContent.includes('活動期間') ? el.parentNode.querySelector('td').textContent : '');
        const retireRaw = pick('th', el => (el.textContent.includes('引退') || el.textContent.includes('退役')) ? el.parentNode.querySelector('td').textContent : '');
        const bodyText = doc.querySelector('#mw-content-text') ? doc.querySelector('#mw-content-text').textContent : '';
        const bodyRetired = /元AV女優|元セクシー女優|AV引退|AV女優を引退|完全引退/.test(bodyText);
        return {
          birthday: birthday,
          age: age,
          height: height,
          weight: '',
          threeSizeText: '',
          braSize: '',
          activeRaw: activeRaw,
          retireRaw: retireRaw,
          bodyRetired: bodyRetired,
          url: wikiUrl
        };
      } catch (e) { return null; }
    },

    computeStatus: function (data) {
      if (!data) return '现役';
      const retireRaw = (data.retireRaw || '').trim();
      if (retireRaw && retireRaw !== '―' && retireRaw !== '-' && retireRaw !== '?' && retireRaw !== '？') return '引退';
      if (data.bodyRetired) return '引退';
      const activeRaw = data.activeRaw || '';
      if (!activeRaw) return '现役';
      if (/引退|退役/.test(activeRaw)) return '引退';
      if (/現在|現役|活動中|継続中/.test(activeRaw)) return '现役';
      const years = activeRaw.match(/\d{4}/g);
      if (!years || years.length < 2) return '现役';
      const endYear = parseInt(years[years.length - 1], 10);
      if (isNaN(endYear)) return '现役';
      const mmMatch = activeRaw.match(new RegExp(endYear + "\\D+?(\\d{1,2})月"));
      const endMonth = mmMatch ? (parseInt(mmMatch[1], 10) - 1) : 11;
      const endDate = new Date(endYear, endMonth + 1, 0);
      const halfYearAgo = new Date();
      halfYearAgo.setMonth(halfYearAgo.getMonth() - 6);
      return endDate < halfYearAgo ? '引退' : '现役';
    },

    getActressData: async function (name) {
      if (!name) return null;
      const cache = this.getLocalCache();
      const cached = cache[name];
      if (cached && cached._ts && (Date.now() - cached._ts < 7 * 86400000)) return cached;
      let data = await this.lookupRepo(name);
      if (!data) data = await this.lookupWiki(name);
      if (data) {
        data.status = this.computeStatus(data);
        data._ts = Date.now();
        cache[name] = data;
        this.saveLocalCache(cache);
        return data;
      }
      return cached || null;
    }
  };

  /* =======================================================================
   * 已收藏女优管理器 (FavoriteActressManager - 工业级高可靠抓取与双向索引)
   * 1. 采用不可变 starId 为主键 + 演员名字/别名索引双重保障
   * 2. 网络层严格携带 credentials: 'same-origin' 并透传反爬/未登录错误诊断
   * 3. 演员主页（/actors/{id}）即时自愈嗅探已收藏状态与按钮监听，毫秒级自动收录
   * 4. 全量深层分页同步（支持多达 300 页海量收藏，彻底解决重度收藏漏爬）
   * 5. 自动剔除系统无效词汇（如“刪除”、“有碼”等）并联动本地已知别名索引
   * 6. 详情页 Chip 渲染与悬浮卡片统一双向识别，杜绝漏判
   * ===================================================================== */
  const FavoriteActressManager = (function () {
    const STORAGE_KEY = 'javdb_fav_actresses';
    const LAST_SYNC_KEY = 'javdb_fav_actresses_sync_time';
    const IGNORE_STRINGS = new Set([
      '刪除', '取消收藏', '收藏', '全部', '演員', '女優', '有碼', '無碼', '歐美', '男優',
      'censored', 'uncensored', 'western', 'rankings', 'actors', 'tags', 'makers', 'series',
      'undefined', 'null'
    ]);
    let memFavs = null; // Set of starIds & normalized names

    function getFavSet() {
      if (memFavs) return memFavs;
      memFavs = new Set();
      let cleaned = false;
      try {
        const raw = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
        if (Array.isArray(raw)) raw.forEach(item => {
          let str = '';
          if (typeof item === 'string') str = item.trim();
          else if (item && typeof item === 'object') {
            if (item.starId) str = String(item.starId).trim();
            else if (item.name) str = String(item.name).trim();
          }
          if (str && !IGNORE_STRINGS.has(str) && str.length >= 2) {
            memFavs.add(str);
          } else if (str) {
            cleaned = true;
          }
        });
      } catch (e) {}
      if (cleaned) saveFavSet();
      return memFavs;
    }

    function saveFavSet() {
      if (!memFavs) return;
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(Array.from(memFavs)));
      } catch (e) {}
    }

    function isFavorite(nameOrId) {
      if (!nameOrId) return false;
      const s = getFavSet();
      const val = String(nameOrId).trim();
      if (!val || IGNORE_STRINGS.has(val)) return false;
      if (s.has(val)) return true;
      // 兼容可能带有的 ♀ ♂ 符号或者空格
      const clean = val.replace(/[\s\u2640\u2642]/g, '');
      if (clean && s.has(clean)) return true;

      // 智能别名联动（例如 田中レモン ↔ 楓カレン / 河北彩花 ↔ 河北彩伽）
      if (typeof ActressService !== 'undefined' && ActressService._idxMem) {
        const idx = ActressService._idxMem;
        if (idx && idx.aliases) {
          const primary1 = idx.aliases[val];
          if (primary1 && (s.has(primary1) || s.has(primary1.replace(/[\s\u2640\u2642]/g, '')))) return true;
          const primary2 = clean ? idx.aliases[clean] : '';
          if (primary2 && (s.has(primary2) || s.has(primary2.replace(/[\s\u2640\u2642]/g, '')))) return true;
        }
      }
      return false;
    }

    function toggleFavorite(name, starId) {
      const s = getFavSet();
      const current = (starId && isFavorite(starId)) || (name && isFavorite(name));
      const willFav = !current;

      const keys = [];
      if (starId && !IGNORE_STRINGS.has(starId)) keys.push(String(starId).trim());
      if (name) {
        const n = String(name).trim();
        if (!IGNORE_STRINGS.has(n)) {
          keys.push(n);
          const clean = n.replace(/[\s\u2640\u2642]/g, '');
          if (clean && clean !== n && !IGNORE_STRINGS.has(clean)) keys.push(clean);
        }
      }

      keys.forEach(k => {
        if (willFav) s.add(k); else s.delete(k);
      });
      saveFavSet();

      // 即时通知当前页面上所有匹配的头像徽章更新
      markBadges(document);
      return willFav;
    }

    // 给指定容器内的所有演员 Chip 头像打上红心徽章 (以 starId 为主, 名字为辅；受「女优信息与收藏标记」开关控制)
    function markBadges(root) {
      const container = root || document;
      const showFavHeart = isPluginEnabled('actressInfo');
      container.querySelectorAll('.emby-actor-chip').forEach(function (chip) {
        const name = (chip.getAttribute('data-actor-name') || (chip.querySelector('.nm') ? chip.querySelector('.nm').textContent : '')).trim();
        const href = chip.getAttribute('href') || '';
        const m = href.match(/\/actors\/([^\/\?\#]+)/);
        const starId = m ? m[1] : '';
        const ava = chip.querySelector('.ava');
        if (ava) {
          const favored = showFavHeart && ((starId && isFavorite(starId)) || (name && isFavorite(name)));
          ava.classList.toggle('is-favorite', favored);
        }
      });
    }

    // 演员个人主页（/actors/{id}）即时嗅探自愈与按钮事件联动
    function autoHarvestActorPage() {
      const m = location.pathname.match(/^\/actors\/([a-zA-Z0-9_-]+)/);
      if (!m) return;
      const starId = m[1];
      if (!starId || IGNORE_STRINGS.has(starId)) return;

      const names = [];
      const titleEl = document.querySelector('h2.title strong, .actor-section h2 strong, .actor-info h2 strong, h2.title');
      if (titleEl && titleEl.textContent) names.push(titleEl.textContent.trim());
      const subTitleEl = document.querySelector('.sub-title, strong.sub-title');
      if (subTitleEl && subTitleEl.textContent) {
        subTitleEl.textContent.split(/[,，\/]/).forEach(p => names.push(p.trim()));
      }
      const docTitle = document.title || '';
      if (docTitle.includes('|')) {
        const t = docTitle.split('|')[0].trim();
        if (t && t.length >= 2) names.push(t);
      }

      const uncollectBtn = document.querySelector('#button-uncollect-actor, a.button-uncollect, a[href*="/uncollect"]');
      const collectBtn = document.querySelector('#button-collect-actor, a.button-collect');

      if (uncollectBtn) {
        // 用户在 JAVDB 上已收藏该演员，毫秒级自动入库
        const s = getFavSet();
        let changed = false;
        if (!s.has(starId)) { s.add(starId); changed = true; }
        names.forEach(n => {
          const clean = n.replace(/[\s\u2640\u2642]/g, '');
          if (clean && clean.length >= 2 && !IGNORE_STRINGS.has(clean)) {
            if (!s.has(clean)) { s.add(clean); changed = true; }
          }
        });
        if (changed) saveFavSet();
      }

      // 绑定原生收藏/取消收藏按钮点击事件
      if (collectBtn && !collectBtn._favBound) {
        collectBtn._favBound = true;
        collectBtn.addEventListener('click', function () {
          setTimeout(function () {
            const s = getFavSet();
            s.add(starId);
            names.forEach(n => {
              const clean = n.replace(/[\s\u2640\u2642]/g, '');
              if (clean && clean.length >= 2 && !IGNORE_STRINGS.has(clean)) s.add(clean);
            });
            saveFavSet();
            markBadges(document);
          }, 600);
        });
      }
      if (uncollectBtn && !uncollectBtn._favBound) {
        uncollectBtn._favBound = true;
        uncollectBtn.addEventListener('click', function () {
          setTimeout(function () {
            const s = getFavSet();
            s.delete(starId);
            names.forEach(n => {
              const clean = n.replace(/[\s\u2640\u2642]/g, '');
              s.delete(clean);
            });
            saveFavSet();
            markBadges(document);
          }, 600);
        });
      }
    }

    // 从 DOM 中提取演员 starId 与名字入库 (超强容错，兼容 JAVDB 各种卡片结构)
    function harvestFromDoc(doc, targetSet) {
      const list = doc || document;
      let count = 0;
      const s = targetSet || getFavSet();

      // 1. 定位所有演员卡片容器
      const cards = list.querySelectorAll('.box.actor-box, .actor-box, #actors .box, #collection-actors .box, .actors .box');
      cards.forEach(function (card) {
        const mainA = card.querySelector('a[href^="/actors/"]:not([href*="uncollect"])') || card.querySelector('a[href*="/actors/"]');
        if (!mainA) return;
        const href = mainA.getAttribute('href') || '';
        const m = href.match(/\/actors\/([a-zA-Z0-9_-]+)/);
        const starId = m ? m[1] : '';
        if (starId && !IGNORE_STRINGS.has(starId) && !s.has(starId)) {
          s.add(starId);
          count++;
        }

        // 提取姓名及别名（title 中常包含所有别名，如："田中檸檬, 田中レモン, 楓カレン, 枫花恋"）
        const titleAttr = (mainA.getAttribute('title') || '').trim();
        const strongText = card.querySelector('strong') ? card.querySelector('strong').textContent.trim() : '';

        const candidateStrings = [];
        if (titleAttr) candidateStrings.push(titleAttr);
        if (strongText) candidateStrings.push(strongText);

        candidateStrings.forEach(rawStr => {
          const parts = rawStr.split(/[,，\/]/).map(p => p.trim()).filter(Boolean);
          parts.forEach(p => {
            const clean = p.replace(/[\s\u2640\u2642]/g, '');
            if (clean && clean.length >= 2 && !IGNORE_STRINGS.has(clean)) {
              if (!s.has(clean)) {
                s.add(clean);
                count++;
              }
            }
          });
        });
      });

      // 兜底策略：如果是在非标准列表页，安全提取合规演员链接
      if (cards.length === 0) {
        const links = list.querySelectorAll('a[href*="/actors/"]:not([href*="uncollect"])');
        links.forEach(function (a) {
          const href = a.getAttribute('href') || '';
          const m = href.match(/\/actors\/([a-zA-Z0-9_-]+)/);
          const starId = m ? m[1] : '';
          if (!starId || IGNORE_STRINGS.has(starId)) return;
          if (!s.has(starId)) { s.add(starId); count++; }

          const txt = (a.getAttribute('title') || a.textContent || '').trim();
          const parts = txt.split(/[,，\/]/).map(p => p.trim()).filter(Boolean);
          parts.forEach(p => {
            const clean = p.replace(/[\s\u2640\u2642]/g, '');
            if (clean && clean.length >= 2 && !IGNORE_STRINGS.has(clean)) {
              if (!s.has(clean)) { s.add(clean); count++; }
            }
          });
        });
      }

      if (!targetSet && count > 0) saveFavSet();
      return count;
    }

    // 真正带 credentials: 'same-origin' 的安全拉取
    async function fetchPageHtml(url) {
      const res = await fetch(url, {
        method: 'GET',
        credentials: 'same-origin',
        headers: {
          'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
          'X-Requested-With': 'XMLHttpRequest'
        }
      });
      if (res.status === 401 || res.status === 403) throw new Error('HTTP ' + res.status + ' 拒绝访问（未登录或需人机验证）');
      if (!res.ok) throw new Error('HTTP ' + res.status + ': ' + res.statusText);
      const text = await res.text();
      const head = text.slice(0, 3000);
      if (/cf-challenge|Checking your browser|Just a moment|__cf_chl/i.test(head)) {
        throw new Error('遭遇 Cloudflare 人机验证，请在新标签页打开 JAVDB 完成人机验证');
      }
      if (/<title[^>]*>\s*(登入|Sign in)|\/login|\/sign_in/i.test(head) && /password|密碼/i.test(text)) {
        throw new Error('未检测到 JAVDB 登录状态，请先在当前浏览器登录 JAVDB 账号后再同步');
      }
      return text;
    }

    // 全量同步抓取已收藏演员（支持多达 300 页海量收藏，友好延时防 429 封禁，双向精准同步）
    async function sync(progressCb) {
      let page = 1;
      let total = 0;
      const maxPages = 300;
      let nextUrl = '/users/collection_actors';
      let lastErr = null;
      const onlineSet = new Set();

      while (nextUrl && page <= maxPages) {
        try {
          if (page > 1) {
            // 友好延时：每页间隔 1200ms，杜绝高频连击触发 Cloudflare 429/403 风控
            await new Promise(r => setTimeout(r, 1200));
          }
          if (progressCb) progressCb('正在同步第 ' + page + ' 页已收藏女优…');
          const html = await fetchPageHtml(nextUrl);
          const parser = new DOMParser();
          const doc = parser.parseFromString(html, 'text/html');
          const added = harvestFromDoc(doc, onlineSet);
          total += added;

          // 寻找显式下一页链接
          const nextA = doc.querySelector('.pagination a.pagination-next, a[rel="next"].pagination-next, a.pagination-next:not([disabled]):not(.is-disabled)');
          let foundHref = '';
          if (nextA && nextA.getAttribute('href') && !nextA.getAttribute('href').startsWith('javascript:')) {
            foundHref = nextA.getAttribute('href');
          }

          if (foundHref) {
            nextUrl = toAbsUrl(foundHref);
            page++;
          } else {
            nextUrl = null;
          }
        } catch (err) {
          lastErr = err;
          break;
        }
      }

      if (lastErr && total === 0 && getCount() === 0) {
        throw lastErr;
      }

      // 双向收敛：成功完成全量遍历时，精准同步线上集合，自动清理已在 JAVDB 取消关注的演员
      const isComplete = !lastErr && nextUrl === null;
      const cur = getFavSet();
      // 防灾熔断：如果本地已有较多收藏，而线上抓取数量断崖式下跌（如下降超过 70%），不执行直接覆盖，避免网页临时改版或会话问题导致清空本地收藏
      const isCatastrophicDrop = cur.size >= 10 && onlineSet.size < Math.floor(cur.size * 0.3);

      if (isComplete && !isCatastrophicDrop && onlineSet.size > 0) {
        memFavs = onlineSet;
      } else if (onlineSet.size > 0) {
        // 若中间某页因网络异常中断、超出最大页数限制或异常收敛，则保守合并未完成的部分
        onlineSet.forEach(function (x) { cur.add(x); });
      }

      // 智能别名扩充：将已收录女优的所有已知别名（如 楓カレン ↔ 田中レモン）自动联动
      try {
        if (typeof ActressService !== 'undefined' && ActressService.getRepoIndex) {
          const idx = await ActressService.getRepoIndex();
          if (idx && idx.aliases) {
            const s = getFavSet();
            const currentList = Array.from(s);
            // 1. 如果已收藏主名，将其别名加入
            for (const alias in idx.aliases) {
              const primary = idx.aliases[alias];
              if (s.has(primary) && !s.has(alias)) {
                s.add(alias);
              }
            }
            // 2. 如果已收藏别名，将其主名加入
            currentList.forEach(name => {
              if (idx.aliases[name]) {
                const primary = idx.aliases[name];
                if (!s.has(primary)) s.add(primary);
              }
            });
          }
        }
      } catch (e) {}

      saveFavSet();
      const curCount = getCount();
      if (curCount === 0 && total === 0) {
        throw new Error('未抓取到任何已收藏演员。请确认你当前账号在 JAVDB 上是否确实有关注的演员');
      }

      if (isComplete && !isCatastrophicDrop) {
        localStorage.setItem(LAST_SYNC_KEY, String(Date.now()));
      }
      markBadges(document);
      return curCount;
    }

    // 后台静默同步（每 24 小时至多 1 次）
    async function autoSync() {
      try {
        const last = parseInt(localStorage.getItem(LAST_SYNC_KEY) || '0', 10);
        const now = Date.now();
        if (now - last < 24 * 3600 * 1000) return;
        await sync();
      } catch (e) {}
    }

    // 穿透传输：真正向 JAVDB 服务端提交收藏/取消收藏请求，实现账号与本地完全双向同步
    async function remoteToggleFavorite(actorName, starId) {
      if (!starId || IGNORE_STRINGS.has(starId)) {
        throw new Error('未识别到有效演员 ID，无法提交至 JAVDB');
      }
      const s = getFavSet();
      const current = isFavorite(starId) || (actorName && isFavorite(actorName));
      const willFav = !current;
      const action = willFav ? 'collect' : 'uncollect';

      // 提取 JAVDB 页面上的 CSRF Token
      const csrfMeta = document.querySelector('meta[name="csrf-token"]');
      const csrf = csrfMeta ? csrfMeta.content : '';

      const bodyData = new URLSearchParams();
      if (csrf) bodyData.append('authenticity_token', csrf);

      const res = await fetch('/actors/' + encodeURIComponent(starId) + '/' + action, {
        method: 'POST',
        credentials: 'same-origin',
        headers: {
          'X-CSRF-Token': csrf,
          'X-Requested-With': 'XMLHttpRequest',
          'Accept': '*/*;q=0.5, text/javascript, application/javascript',
          'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8'
        },
        body: bodyData.toString()
      });

      if (res.status === 401 || res.status === 403) {
        throw new Error('未检测到 JAVDB 登录状态，请先登录 JAVDB 账号');
      }
      if (!res.ok) {
        throw new Error('JAVDB 响应异常 (HTTP ' + res.status + ')');
      }

      // 服务端成功写入，更新本地数据库与视图
      const keys = [];
      if (starId && !IGNORE_STRINGS.has(starId)) keys.push(String(starId).trim());
      if (actorName) {
        const n = String(actorName).trim();
        if (!IGNORE_STRINGS.has(n)) {
          keys.push(n);
          const clean = n.replace(/[\s\u2640\u2642]/g, '');
          if (clean && clean !== n && !IGNORE_STRINGS.has(clean)) keys.push(clean);
        }
      }

      keys.forEach(k => {
        if (willFav) s.add(k); else s.delete(k);
      });
      saveFavSet();
      markBadges(document);
      return willFav;
    }

    function getCount() {
      return getFavSet().size;
    }

    function dump() {
      return Array.from(getFavSet());
    }

    return {
      isFavorite: isFavorite,
      toggleFavorite: toggleFavorite,
      remoteToggleFavorite: remoteToggleFavorite,
      markBadges: markBadges,
      autoHarvestActorPage: autoHarvestActorPage,
      harvestFromDoc: harvestFromDoc,
      sync: sync,
      autoSync: autoSync,
      getCount: getCount,
      dump: dump
    };
  })();

  // 暴露到全局，便于用户在控制台自检调试
  if (typeof window !== 'undefined') window.FavoriteActressManager = FavoriteActressManager;

  /* =======================================================================
   * 演员头像高清替换服务 (Gfriends Avatar Service)
   * 优先从 gfriends 高清头像库匹配头像（不分男女，有图即用），未匹配则平滑回退 JAVDB 官方头像或默认图
   * 使用 IndexedDB (meta 表) 存储倒排索引，内存常驻 Map，TTL 7天，零污染收藏夹数据库
   * ===================================================================== */
  const GfriendsAvatarService = (function () {
    const CDN_BASE = 'https://testingcf.jsdelivr.net/gh/gfriends/gfriends@master';
    const FALLBACK_BASE = 'https://raw.githubusercontent.com/gfriends/gfriends/master';
    const META_KEY = 'gfriends_actor_index_v3'; // 全量收录无性别限制的高清头像索引
    const TTL_MS = 7 * 24 * 60 * 60 * 1000; // 7 天缓存

    let indexMap = null; // Map<string, string>: actressName -> "folder/filename"
    let loadPromise = null;

    function buildUrl(base, relPath) {
      if (!relPath) return '';
      const slashIdx = relPath.indexOf('/');
      if (slashIdx === -1) return '';
      const folder = relPath.slice(0, slashIdx);
      const fileWithQuery = relPath.slice(slashIdx + 1);
      const qIdx = fileWithQuery.indexOf('?');
      let filename = fileWithQuery;
      let query = '';
      if (qIdx !== -1) {
        filename = fileWithQuery.slice(0, qIdx);
        query = fileWithQuery.slice(qIdx);
      }
      return base.replace(/\/+$/, '') + '/Content/' + encodeURIComponent(folder) + '/' + encodeURIComponent(filename) + query;
    }

    async function fetchIndex() {
      // 1. 尝试从 IndexedDB meta 表读取有效缓存
      try {
        if (typeof FAV !== 'undefined' && typeof FAV.dbGetMeta === 'function') {
          const cached = await FAV.dbGetMeta(META_KEY);
          if (cached && cached.time && cached.map && (Date.now() - cached.time < TTL_MS)) {
            indexMap = new Map(Object.entries(cached.map));
            log('Gfriends 头像索引从 IndexedDB 恢复成功，收录女优: ' + indexMap.size + ' 位');
            return indexMap;
          }
        }
      } catch (e) {
        log('读取 Gfriends IndexedDB 缓存异常: ' + e.message);
      }

      // 2. 从 CDN 下载 Filetree.json（jsDelivr testingcf 优先，多节点轮询，GitHub Raw 兜底）
      let text = '';
      const bases = [
        CDN_BASE,
        'https://cdn.jsdelivr.net/gh/gfriends/gfriends@master',
        'https://fastly.jsdelivr.net/gh/gfriends/gfriends@master',
        FALLBACK_BASE
      ];
      for (const b of bases) {
        try {
          const url = b + '/Filetree.json';
          log('正在下载 Gfriends 头像索引树: ' + url);
          text = await gmHttp.get(url);
          if (text && text.length > 1000) break;
        } catch (err) {
          log('下载 Gfriends 索引树失败 (' + b + '): ' + err.message);
        }
      }

      if (!text) {
        log('Gfriends 头像索引树获取失败，将继续使用官方头像');
        return null;
      }

      try {
        const data = JSON.parse(text);
        const content = data.Content || {};
        const compactObj = {};
        for (const folder of Object.keys(content)) {
          const files = content[folder];
          if (!files || typeof files !== 'object') continue;
          for (const rawKey of Object.keys(files)) {
            const name = rawKey.replace(/\.(jpg|jpeg|png|webp)$/i, '').trim();
            if (name) {
              compactObj[name] = folder + '/' + files[rawKey];
            }
          }
        }

        indexMap = new Map(Object.entries(compactObj));
        log('Gfriends 头像索引构建完成，共收录 ' + indexMap.size + ' 位演员头像');

        // 异步存入 IndexedDB
        if (typeof FAV !== 'undefined' && typeof FAV.dbSetMeta === 'function') {
          FAV.dbSetMeta(META_KEY, { time: Date.now(), map: compactObj }).catch(function (err) {
            log('保存 Gfriends 索引至 IndexedDB 异常: ' + err.message);
          });
        }

        return indexMap;
      } catch (err) {
        log('解析 Gfriends 索引 JSON 失败: ' + err.message);
        return null;
      }
    }

    function ensureLoaded() {
      if (indexMap) return Promise.resolve(indexMap);
      if (!loadPromise) {
        loadPromise = fetchIndex().then(function (res) {
          loadPromise = null;
          if (res) {
            try { refreshAllAvatarsUI(); } catch (e) {}
          }
          return res;
        }).catch(function (err) {
          loadPromise = null;
          return null;
        });
      }
      return loadPromise;
    }

    // 智能别名与名称规范化匹配
    function getAvatarUrl(name, fallbackOfficialUrl) {
      if (!isPluginEnabled('gfriendsAvatar')) {
        return fallbackOfficialUrl || '';
      }
      if (!name || typeof name !== 'string') {
        return fallbackOfficialUrl || '';
      }
      const cleanName = name.replace(/[\s\u2640\u2642]/g, '').trim();
      if (!cleanName) return fallbackOfficialUrl || '';

      if (!indexMap) {
        ensureLoaded();
        return fallbackOfficialUrl || '';
      }

      // 1. 直接匹配
      let relPath = indexMap.get(cleanName) || indexMap.get(name.trim());
      // 2. 别名候选匹配（若有符号分割，如 "枫花恋 / 田中柠檬"）
      if (!relPath && /[,，\/]/.test(name)) {
        const parts = name.split(/[,，\/]/).map(function (p) { return p.replace(/[\s\u2640\u2642]/g, '').trim(); }).filter(Boolean);
        for (let i = 0; i < parts.length; i++) {
          relPath = indexMap.get(parts[i]);
          if (relPath) break;
        }
      }

      // 3. 复用 ActressService 别名映射库进行简繁体与艺名转换（如 三上悠亚 -> 三上悠亜 / 安齋拉拉 -> 安齋らら）
      if (!relPath && typeof ActressService !== 'undefined' && ActressService._idxMem && ActressService._idxMem.aliases) {
        const aliasTarget = ActressService._idxMem.aliases[cleanName] || ActressService._idxMem.aliases[name.trim()];
        if (aliasTarget) {
          const cleanAlias = aliasTarget.replace(/[\s\u2640\u2642]/g, '').trim();
          relPath = indexMap.get(cleanAlias) || indexMap.get(aliasTarget);
        }
      }

      if (relPath) {
        return buildUrl(CDN_BASE, relPath);
      }
      return fallbackOfficialUrl || '';
    }

    // 页面启动后预热加载
    setTimeout(function () {
      if (isPluginEnabled('gfriendsAvatar')) {
        ensureLoaded();
      }
    }, 1200);

    return {
      ensureLoaded: ensureLoaded,
      getAvatarUrl: getAvatarUrl,
      buildUrl: buildUrl,
      hasLoaded: function () { return !!indexMap; }
    };
  })();

  // 页面上所有女优头像的响应式动态刷新（开关切换/异步索引加载完成时触发）
  function refreshAllAvatarsUI() {
    const isEnabled = isPluginEnabled('gfriendsAvatar');
    document.querySelectorAll('img[data-gfriends-actress]').forEach(function (img) {
      const actName = img.getAttribute('data-gfriends-actress');
      const offAva = img.getAttribute('data-official-avatar') || '';
      if (!actName) return;

      if (isEnabled && typeof GfriendsAvatarService !== 'undefined') {
        const gfUrl = GfriendsAvatarService.getAvatarUrl(actName, offAva);
        if (gfUrl && gfUrl !== offAva && !img.getAttribute('data-gf-failed')) {
          img.src = gfUrl;
          img.style.display = '';
          const pAva = img.closest('.ava, .efav-actor-ava-wrap');
          if (pAva) {
            pAva.style.backgroundImage = 'url(\'' + encodeURI(gfUrl).replace(/['"()]/g, '') + '\')';
          }
          if (img.nextElementSibling && img.nextElementSibling.classList.contains('efav-actor-ava-fallback')) {
            img.nextElementSibling.style.display = 'none';
          }
          return;
        }
      }

      // 插件关闭或未在 Gfriends 匹配：回退官方头像
      if (offAva) {
        img.src = offAva;
        img.style.display = '';
        const pAva = img.closest('.ava, .efav-actor-ava-wrap');
        if (pAva) {
          pAva.style.backgroundImage = 'url(\'' + encodeURI(offAva).replace(/['"()]/g, '') + '\')';
        }
        if (img.nextElementSibling && img.nextElementSibling.classList.contains('efav-actor-ava-fallback')) {
          img.nextElementSibling.style.display = 'none';
        }
      } else {
        img.style.display = 'none';
        const pAva = img.closest('.ava, .efav-actor-ava-wrap');
        if (pAva) {
          pAva.style.backgroundImage = '';
        }
        if (img.nextElementSibling && img.nextElementSibling.classList.contains('efav-actor-ava-fallback')) {
          img.nextElementSibling.style.display = 'inline-flex';
        }
      }
    });
  }

  if (typeof window !== 'undefined') {
    window.GfriendsAvatarService = GfriendsAvatarService;
    window.refreshAllAvatarsUI = refreshAllAvatarsUI;
  }

