  function getInfoSiteConfigs() {
    try {
      const raw = localStorage.getItem('javdb_info_sites');
      if (raw) {
        const arr = JSON.parse(raw);
        if (Array.isArray(arr) && arr.length) {
          const defMap = {};
          DEFAULT_INFO_SITES.forEach(function (d) { defMap[d.id] = d; });
          const existingIds = new Set();
          arr.forEach(function (s) {
            existingIds.add(s.id);
            if (defMap[s.id]) {
              if (!s.icon) s.icon = defMap[s.id].icon;
              if (s.enabled === undefined) s.enabled = true;
            }
          });
          DEFAULT_INFO_SITES.forEach(function (d) {
            if (!existingIds.has(d.id)) {
              arr.push(JSON.parse(JSON.stringify(d)));
            }
          });
          return arr;
        }
      }
    } catch (e) {}
    return JSON.parse(JSON.stringify(DEFAULT_INFO_SITES));
  }

  function saveInfoSiteConfigs(configs) {
    try { localStorage.setItem('javdb_info_sites', JSON.stringify(configs)); } catch (e) {}
  }

  function buildInfoSitesHtml(code) {
    if (!code) return '';
    const sites = getInfoSiteConfigs().filter(function (s) { return s.enabled !== false; });
    if (!sites.length) return '';

    let html = '<span class="emby-info-sites" id="emby-info-sites">';
    html += '<span class="emby-info-sites-divider" title="信息站点"></span>';
    sites.forEach(function (s) {
      const url = buildSitePlayUrl(s, code);
      const safeId = String(s.id).replace(/[^a-zA-Z0-9_-]/g, '_');
      const fullTitle = s.name + ' 一键跳转 (' + code + ')';
      const iconUrl = s.icon || '';
      html +=
        '<a class="emby-info-site-btn emby-info-site-' + escapeAttr(safeId) + '" href="' + escapeAttr(url) + '" target="_blank" rel="noopener" title="' + escapeAttr(fullTitle) + '">' +
          renderSiteLogoHtml(iconUrl, s.name, s.id) +
        '</a>';
    });
    html += '</span>';
    return html;
  }

  function getPlaySiteConfigs() {
    try {
      const raw = localStorage.getItem('javdb_play_sites');
      if (raw) {
        let arr = JSON.parse(raw);
        if (Array.isArray(arr) && arr.length) {
          // 解耦信息站点：从播放源中过滤掉 javbus 与 group 为「信息」的站点
          const beforeLen = arr.length;
          arr = arr.filter(function (s) { return s.id !== 'javbus' && s.group !== '信息'; });
          let needsResave = (arr.length !== beforeLen);
          // 补齐旧缓存可能缺失的 icon / group 字段，自动自愈升级失效旧域名，并合入新增预设站点
          const defMap = {};
          DEFAULT_PLAY_SITES.forEach(function (d) { defMap[d.id] = d; });
          const existingIds = new Set();
          arr.forEach(function (s) {
            existingIds.add(s.id);
            // 自动治愈迁移旧版本可能残留的失效/废弃域名
            if (s.template) {
              if (s.template.includes('javmost.cx')) {
                s.template = s.template.replace('javmost.cx', 'www.javmost.ws');
                needsResave = true;
              }
              if (s.template.includes('missav.ws')) {
                s.template = s.template.replace('missav.ws', 'missav.live');
                needsResave = true;
              }
              if (s.template.includes('njavtv.blog/video/')) {
                s.template = s.template.replace('njavtv.blog/video/', 'njavtv.blog/search?keyword=');
                needsResave = true;
              }
            }
            if (s.icon) {
              if (s.icon.includes('javmost.cx')) {
                s.icon = s.icon.replace('javmost.cx', 'www.javmost.ws');
                needsResave = true;
              }
              if (s.icon.includes('missav.ws')) {
                s.icon = s.icon.replace('missav.ws', 'missav.live');
                needsResave = true;
              }
              if (s.id === 'av01' && (!s.icon || s.icon.includes('av01.media') || s.icon.includes('duckduckgo') || s.icon.includes('favicon.ico'))) {
                s.icon = 'https://www.av01.xyz/static/pwa-192x192.png';
                needsResave = true;
              }
              if (s.icon.includes('javsubtitled.com/javsubtitled.ico')) {
                s.icon = 'https://icons.duckduckgo.com/ip3/javsubtitled.com.ico';
                needsResave = true;
              }
              if (s.icon.includes('cdn.javmiku.com')) {
                s.icon = 'https://jav.guru/favicon.ico';
                needsResave = true;
              }
            }
            if (defMap[s.id]) {
              if (!s.icon) s.icon = defMap[s.id].icon;
              if (!s.group) s.group = defMap[s.id].group;
            } else if (!s.group) {
              s.group = s.id && s.id.startsWith('custom_') ? '自定义' : '其他';
            }
          });
          // 补充未在本地配置中出现过的默认站点
          DEFAULT_PLAY_SITES.forEach(function (d) {
            if (!existingIds.has(d.id)) {
              arr.push(JSON.parse(JSON.stringify(d)));
              needsResave = true;
            }
          });
          if (needsResave) {
            savePlaySiteConfigs(arr);
          }
          return arr;
        }
      }
    } catch (e) {}
    return JSON.parse(JSON.stringify(DEFAULT_PLAY_SITES));
  }

