  function getSiteInitial(name, id) {
    if (id === 'javdb_native' || id === 'javdb') return 'DB';
    if (!name) return '▶';
    const clean = String(name).replace(/播放|站点|search/gi, '').trim();
    if (/^123/i.test(clean)) return '123';
    if (/^njav/i.test(clean)) return 'NJ';
    if (/^miss/i.test(clean)) return 'M';
    if (/^jable/i.test(clean)) return 'J';
    if (/^sup/i.test(clean)) return 'SJ';
    if (/guru/i.test(clean) || /javguru/i.test(id)) return 'JG';
    if (/most/i.test(clean) || /javmost/i.test(id)) return 'JM';
    if (/^bus/i.test(clean) || /javbus/i.test(clean) || /javbus/i.test(id)) return 'JB';
    if (/^lib/i.test(clean) || /javlib/i.test(clean) || /javlib/i.test(id)) return 'JL';
    if (/^fanza/i.test(clean) || /dmm/i.test(clean) || /fanza/i.test(id)) return 'FZ';
    if (/^txt/i.test(clean) || /javtxt/i.test(clean) || /javtxt/i.test(id)) return 'JT';
    if (/^trail/i.test(clean) || /javtrailers/i.test(clean) || /javtrailers/i.test(id)) return 'TR';
    if (/^av01/i.test(clean) || /av01/i.test(id)) return 'AV';
    if (/theav/i.test(clean) || /theav/i.test(id)) return 'TA';
    if (/preview/i.test(clean) || /avpreview/i.test(id)) return 'AP';
    if (/subtitled/i.test(clean) || /javsubtitled/i.test(id)) return 'JS';
    if (/^7mm/i.test(clean) || /7mmtv/i.test(id)) return '7M';
    if (/avmates/i.test(clean) || /avmates/i.test(id)) return 'AM';
    if (/hohoj/i.test(clean) || /hohoj/i.test(id)) return 'HH';
    if (/javfree/i.test(clean) || /javfree/i.test(id)) return 'JF';
    if (/javstore/i.test(clean) || /javstore/i.test(id)) return 'JS';
    if (/blogjav/i.test(clean) || /blogjav/i.test(id)) return 'BJ';
    if (/local/i.test(id)) return 'DB';
    if (/xsz/i.test(clean) || /xsz/i.test(id)) return 'XS';
    if (/javhd/i.test(clean) || /javhd/i.test(id)) return 'HD';
    return clean.slice(0, 2).toUpperCase() || '▶';
  }

  function renderSiteLogoHtml(iconUrl, name, id) {
    const initial = escapeHtml(getSiteInitial(name, id));
    if (!iconUrl) {
      return '<span class="emby-site-logo-wrap"><span class="emby-site-logo-fallback">' + initial + '</span></span>';
    }
    // 关键防盗链与兜底策略：
    // 1. referrerpolicy="no-referrer" 消除向外部站点传递 Referer: javdb.com，破解防盗链/反爬 403；
    // 2. 首次 onerror 时自动尝试通过 DuckDuckGo Favicon CDN 兜底；二次失败才平滑回退为纯文字微标。
    const errHandler =
      "if(!this.dataset.fb){" +
        "this.dataset.fb='1';" +
        "try{" +
          "var h=new URL(this.src).hostname;" +
          "if(h&&h.indexOf('duckduckgo')===-1){this.src='https://icons.duckduckgo.com/ip3/'+h+'.ico';return;}" +
        "}catch(e){}" +
      "}" +
      "this.style.display='none';" +
      "if(this.nextElementSibling)this.nextElementSibling.style.display='inline-flex';";

    return (
      '<span class="emby-site-logo-wrap">' +
        '<img class="emby-site-logo" src="' + escapeAttr(iconUrl) + '" alt="" loading="lazy" referrerpolicy="no-referrer" ' +
          'onerror="' + escapeAttr(errHandler) + '" />' +
        '<span class="emby-site-logo-fallback" style="display:none;">' + initial + '</span>' +
      '</span>'
    );
  }

  function buildSitePlayUrl(site, code) {
    if (!site || !site.template || !code) return '#';
    const c = String(code).trim();
    const raw = site.template
      .replace(/\{code\}/g, encodeURIComponent(c))
      .replace(/\{code_lower\}/g, encodeURIComponent(c.toLowerCase()))
      .replace(/\{code_upper\}/g, encodeURIComponent(c.toUpperCase()));
    return safeHref(raw, '#');
  }

  function getSiteBadgeClass(group) {
    const g = String(group || '').trim();
    if (g === '官方') return 'emby-site-badge-official';
    if (g === '主力') return 'emby-site-badge-main';
    if (g === '主流') return 'emby-site-badge-hot';
    if (g === '综合') return 'emby-site-badge-general';
    if (g === '预告') return 'emby-site-badge-trailer';
    if (g === '信息') return 'emby-site-badge-info';
    return 'emby-site-badge-default';
  }

  // 片源在线检测会话级缓存：Map<"siteId_CODE", { val: boolean, exp: number }>
  const siteAvailabilityCache = new Map();
  function getCachedSiteAvailability(key) {
    const item = siteAvailabilityCache.get(key);
    if (!item) return undefined;
    if (Date.now() > item.exp) {
      siteAvailabilityCache.delete(key);
      return undefined;
    }
    return item.val;
  }
  function setCachedSiteAvailability(key, val) {
    // 成功有效可用状态缓存 5 分钟，失败/不可用状态缓存 1 分钟（避免临时网络抖动导致全天不可用）
    const ttl = val ? 300000 : 60000;
    siteAvailabilityCache.set(key, { val: val, exp: Date.now() + ttl });
  }

  async function checkSiteAvailability(site, code, root) {
    if (!site || !code) return false;
    const cleanCode = String(code).trim();
    const cacheKey = (site.id || 'unknown') + '_' + cleanCode.toUpperCase();
    const cached = getCachedSiteAvailability(cacheKey);
    if (typeof cached === 'boolean') {
      return cached;
    }

    // 1. JAVDB 原生官方播放检测
    if (site.id === 'javdb_native' || site.id === 'javdb' || site.isNative) {
      const nativePlay = root ? extractNativePlayInfo(root) : null;
      const res = !!nativePlay;
      setCachedSiteAvailability(cacheKey, res);
      return res;
    }

    // 2. 外部站点 URL 构造与域名自愈
    let targetUrl = buildSitePlayUrl(site, cleanCode);
    if (!targetUrl || targetUrl === '#') {
      setCachedSiteAvailability(cacheKey, false);
      return false;
    }
    if (targetUrl.includes('javmost.cx')) {
      targetUrl = targetUrl.replace('javmost.cx', 'www.javmost.ws');
    }
    if (targetUrl.includes('missav.ws')) {
      targetUrl = targetUrl.replace('missav.ws', 'missav.live');
    }

    // 正则匹配番号（容错横杠连字符）
    const escapedCode = cleanCode.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const codeRegex = new RegExp(escapedCode.replace(/[-_]/g, '[-_]?'), 'i');

    const reqFn = typeof GM_xmlhttpRequest !== 'undefined'
      ? GM_xmlhttpRequest
      : (typeof gmHttp !== 'undefined' && gmHttp.request ? gmHttp.request.bind(gmHttp) : null);

    if (!reqFn) return false;

    // 单次探针请求封装（纯净请求头，不显式伪造 Referer 与 User-Agent，交由 Tampermonkey 原生环境发包穿透 Cloudflare）
    function sendProbe(url, timeoutMs) {
      return new Promise(function (resolve) {
        try {
          reqFn({
            method: 'GET',
            url: url,
            timeout: timeoutMs || 12000,
            headers: {
              'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'
            },
            onload: function (resp) {
              resolve({
                status: resp.status,
                text: resp.responseText || '',
                finalUrl: resp.finalUrl || url
              });
            },
            onerror: function () { resolve({ status: 0, text: '', error: true }); },
            ontimeout: function () { resolve({ status: 0, text: '', timeout: true }); }
          });
        } catch (e) {
          resolve({ status: 0, text: '', error: true });
        }
      });
    }

    // 各站点特征判定逻辑
    function evaluateResult(siteId, status, txt) {
      if (!txt || status >= 400 || status === 0) return false;

      // 通用否定关键词排除（只有在页面无番号卡片特征且出现明确未找到提示时才生效）
      const hasNegative = /404 Not Found|没有找到相关|未找到视频|未找到相关的影片|No videos found|抱歉，没有找到|Nothing Found|找不到任何內容/i.test(txt);
      if (hasNegative && !codeRegex.test(txt)) return false;

      // 站点定制判别
      if (siteId === '123av') {
        return (txt.includes('detail') || txt.includes('/v/') || txt.includes('video') || codeRegex.test(txt)) && codeRegex.test(txt);
      } else if (siteId === 'njavtv') {
        return codeRegex.test(txt);
      } else if (siteId === 'njav.com') {
        return codeRegex.test(txt);
      } else if (siteId === 'njav') {
        return codeRegex.test(txt);
      } else if (siteId === 'missav') {
        return !txt.includes('Page Not Found') && codeRegex.test(txt);
      } else if (siteId === 'jable') {
        return txt.includes('info-header') || txt.includes('video-img-box') || txt.includes('detail') || codeRegex.test(txt);
      } else if (siteId === 'netflav') {
        return (txt.includes('/video?') || txt.includes('grid_0') || codeRegex.test(txt)) && codeRegex.test(txt);
      } else if (siteId === 'supjav') {
        return (txt.includes('post') || txt.includes('posts') || codeRegex.test(txt)) && codeRegex.test(txt);
      } else if (siteId === 'bestjavporn') {
        return (txt.includes('thumb-block') || txt.includes('video') || codeRegex.test(txt)) && codeRegex.test(txt);
      } else if (siteId === 'javmenu') {
        return (txt.includes('video-item') || txt.includes('card') || codeRegex.test(txt)) && codeRegex.test(txt);
      } else if (siteId === 'javguru') {
        return (txt.includes('inside-article') || txt.includes('imgg') || codeRegex.test(txt)) && codeRegex.test(txt);
      } else if (siteId === 'javmost') {
        return (txt.includes('card') || txt.includes('myButton') || codeRegex.test(txt)) && codeRegex.test(txt);
      } else if (siteId === 'javbus') {
        return status === 200 && (txt.includes('bigImage') || txt.includes('movie') || codeRegex.test(txt));
      } else {
        return status === 200 && codeRegex.test(txt);
      }
    }

    try {
      let isAvailable = false;
      let shouldCache = false;

      // 针对 Jable 实施智能多级探针：先探测模板检索页，若未果尝试正片直链与中文字幕直链
      if (site.id === 'jable') {
        let resp = await sendProbe(targetUrl, 10000);
        if (resp.status === 200 && evaluateResult('jable', resp.status, resp.text)) {
          isAvailable = true;
          shouldCache = true;
        } else {
          // 备选探针1：直链 /videos/{code}/
          const videoUrl = 'https://jable.tv/videos/' + encodeURIComponent(cleanCode.toLowerCase()) + '/';
          let resp2 = await sendProbe(videoUrl, 8000);
          if (resp2.status === 200 && evaluateResult('jable', resp2.status, resp2.text)) {
            isAvailable = true;
            shouldCache = true;
          } else {
            // 备选探针2：中文字幕直链 /videos/{code}-c/
            const subUrl = 'https://jable.tv/videos/' + encodeURIComponent(cleanCode.toLowerCase()) + '-c/';
            let resp3 = await sendProbe(subUrl, 8000);
            if (resp3.status === 200 && evaluateResult('jable', resp3.status, resp3.text)) {
              isAvailable = true;
              shouldCache = true;
            } else if (resp.status > 0 || resp2.status > 0 || resp3.status > 0) {
              shouldCache = true;
            }
          }
        }
      } else {
        // 其余站点直接基于配置的 targetUrl 探测
        const resp = await sendProbe(targetUrl, 12000);
        if (resp.status === 200) {
          isAvailable = evaluateResult(site.id, resp.status, resp.text);
          shouldCache = true;
        } else if (resp.status >= 400) {
          isAvailable = false;
          shouldCache = true;
        }
      }

      if (isAvailable) {
        setCachedSiteAvailability(cacheKey, true);
        return true;
      } else {
        if (shouldCache) {
          setCachedSiteAvailability(cacheKey, false);
        }
        return false;
      }
    } catch (e) {
      return false;
    }
  }

  /* =======================================================================
   * Git 云端备份与恢复客户端 (支持 GitHub / Gitee 等标准 REST API)
   * ===================================================================== */
  class GitBackupClient {
    constructor(apiUrl, repo, branch, token, folderName) {
      const base = (apiUrl || 'https://api.github.com').trim();
      this.apiUrl = base.endsWith('/') ? base.slice(0, -1) : base;
      this.repo = (repo || '').trim();
      this.branch = (branch || 'main').trim();
      this.token = (token || '').trim();
      this.folderName = (folderName || 'JavdbEmbySkin_backup').replace(/^\/+|\/+$/g, '');
    }

    isGitee() {
      return this.apiUrl.includes('gitee.com');
    }

    buildHeaders(extra) {
      const h = Object.assign({
        'Accept': 'application/vnd.github+json',
        'User-Agent': 'JAVDB-Emby-Skin-Backup',
        'X-GitHub-Api-Version': '2022-11-28'
      }, extra || {});
      if (this.token) {
        h['Authorization'] = this.token.startsWith('Bearer ') ? this.token : ('Bearer ' + this.token);
      }
      return h;
    }

    request(method, path, body, extraHeaders) {
      const self = this;
      return new Promise(function (resolve, reject) {
        let url = self.apiUrl + path;
        if (self.isGitee() && self.token && !url.includes('access_token=')) {
          url += (url.includes('?') ? '&' : '?') + 'access_token=' + encodeURIComponent(self.token);
        }
        const headers = self.buildHeaders(extraHeaders);
        if (body !== undefined && !headers['Content-Type']) {
          headers['Content-Type'] = 'application/json;charset=UTF-8';
        }

        gmHttp.request({
          method: method,
          url: url,
          headers: headers,
          data: body !== undefined ? JSON.stringify(body) : undefined,
          timeout: 20000
        }).then(function (text) {
          resolve(text);
        }).catch(function (err) {
          reject(new Error('Git 请求失败: ' + (err.message || err)));
        });
      });
    }

    async testConnection() {
      // 验证仓库访问与 Token 权限
      const repoPath = '/repos/' + this.repo;
      let text;
      try {
        text = await this.request('GET', repoPath);
      } catch (err) {
        const msg = String(err.message || err);
        if (msg.includes('404') || msg.includes('Not Found')) {
          throw new Error('仓库不存在，或当前 Token 没有权限访问该私有仓库（请检查仓库名大小写及精细化令牌的选定仓库）');
        }
        if (msg.includes('401') || msg.includes('Bad credentials')) {
          throw new Error('访问令牌 (Token) 无效或已过期，请重新生成');
        }
        if (msg.includes('403')) {
          throw new Error('API 访问被拒绝 (403)，请确认 Token 是否勾选了 Contents (内容) 读写权限');
        }
        throw err;
      }
      let info;
      try {
        info = JSON.parse(text);
      } catch (e) {
        throw new Error('解析 Git 响应数据失败');
      }
      if (!info || (!info.id && !info.full_name && !info.name)) {
        throw new Error('未获取到有效的仓库信息');
      }
      return {
        name: info.full_name || info.name || this.repo,
        private: !!info.private,
        defaultBranch: info.default_branch || 'main',
        permissions: info.permissions || null
      };
    }

    contentsPath(filename) {
      const p = filename ? (this.folderName + '/' + filename) : this.folderName;
      const encodedPath = p.split('/').map(encodeURIComponent).join('/');
      return '/repos/' + this.repo + '/contents/' + encodedPath + '?ref=' + encodeURIComponent(this.branch);
    }

    async fetchFileMeta(filename) {
      try {
        const text = await this.request('GET', this.contentsPath(filename));
        const parsed = JSON.parse(text);
        if (parsed && (parsed.sha || parsed.type === 'file')) return parsed;
        return null;
      } catch (e) {
        if (e.message && (e.message.includes('404') || e.message.includes('Not Found'))) return null;
        throw e;
      }
    }

    async backup(filename, content) {
      const meta = await this.fetchFileMeta(filename);
      const utf8Bytes = new TextEncoder().encode(content);
      let binaryStr = '';
      for (let i = 0; i < utf8Bytes.length; i++) binaryStr += String.fromCharCode(utf8Bytes[i]);
      const base64Content = btoa(binaryStr);

      const body = {
        message: 'javdb-backup: ' + filename + ' ' + new Date().toISOString(),
        content: base64Content,
        branch: this.branch
      };
      if (meta && meta.sha) body.sha = meta.sha;

      const method = this.isGitee() ? (meta ? 'PUT' : 'POST') : 'PUT';
      await this.request(method, this.contentsPath(filename), body);
      return true;
    }

    async fetchLastCommitDate(filename) {
      try {
        const p = filename ? (this.folderName + '/' + filename) : this.folderName;
        const commitPath = '/repos/' + this.repo + '/commits?path=' + encodeURIComponent(p) + '&sha=' + encodeURIComponent(this.branch);
        const text = await this.request('GET', commitPath);
        const list = JSON.parse(text);
        if (Array.isArray(list) && list[0] && list[0].commit) {
          return list[0].commit.committer?.date || list[0].commit.author?.date || '';
        }
      } catch (e) {}
      return '';
    }

    async getBackupList() {
      let text;
      try {
        text = await this.request('GET', this.contentsPath());
      } catch (e) {
        if (e.message && (e.message.includes('404') || e.message.includes('Not Found'))) return [];
        throw e;
      }
      let entries = [];
      try {
        const parsed = JSON.parse(text);
        if (Array.isArray(parsed)) entries = parsed;
      } catch (e) {
        return [];
      }

      const files = entries.filter(function (e) { return e.type === 'file' && e.name.endsWith('.json'); });
      const self = this;
      const items = await Promise.all(files.map(async function (e) {
        let date = '';
        try { date = await self.fetchLastCommitDate(e.name); } catch (_) {}
        return {
          fileId: e.name,
          name: e.name,
          size: e.size || 0,
          createTime: date,
          sha: e.sha,
          download_url: e.download_url
        };
      }));
      items.reverse();
      return items;
    }

    async getFileContent(filename) {
      let text = null;
      if (!this.isGitee()) {
        try {
          // GitHub 专属 Raw 媒体类型：直接拉取原生文件文本，彻底避开 1MB 截断与 Base64 编码限制
          const rawText = await this.request('GET', this.contentsPath(filename), undefined, {
            'Accept': 'application/vnd.github.raw+json, application/vnd.github.raw'
          });
          if (typeof rawText === 'string' && rawText.trim().startsWith('{')) {
            try {
              const testObj = JSON.parse(rawText);
              // 若返回的是 GitHub Contents API 信封结构（含 content 且 encoding 为 base64），不能直接当正文返回，记录为 text 供后续 base64 解码
              if (testObj && typeof testObj.content === 'string' && testObj.encoding === 'base64') {
                text = rawText;
              } else if (testObj && (testObj.movies || testObj.lists || testObj.version || testObj.app || testObj.config || testObj.notes)) {
                return rawText;
              }
            } catch (_) {
              return rawText;
            }
          }
        } catch (_) {}
      }
      if (!text) {
        text = await this.request('GET', this.contentsPath(filename));
      }
      let parsed = null;
      try { parsed = JSON.parse(text); } catch (_) {}
      if (parsed && typeof parsed.content === 'string' && parsed.content.trim().length > 0) {
        const bin = atob(parsed.content.replace(/\s+/g, ''));
        const bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
        return new TextDecoder('utf-8').decode(bytes);
      }
      if (parsed && parsed.download_url) {
        const dlHeaders = {};
        if (this.token && !this.isGitee()) {
          dlHeaders['Authorization'] = this.token.startsWith('Bearer ') ? this.token : ('Bearer ' + this.token);
        }
        return await gmHttp.request({ method: 'GET', url: parsed.download_url, headers: dlHeaders });
      }
      return text;
    }

    async deleteFile(filename, sha) {
      let fileSha = sha;
      if (!fileSha) {
        const meta = await this.fetchFileMeta(filename);
        if (!meta || !meta.sha) throw new Error('文件不存在或已被删除');
        fileSha = meta.sha;
      }
      const body = {
        message: 'javdb-delete: ' + filename + ' ' + new Date().toISOString(),
        sha: fileSha,
        branch: this.branch
      };
      await this.request('DELETE', this.contentsPath(filename), body);
      return true;
    }
  }

  /* =======================================================================
   * WebDAV 云端备份与恢复客户端
   * ===================================================================== */
  class WebDavClient {
    constructor(url, username, password) {
      const u = (url || '').trim();
      this.baseUrl = u ? (u.endsWith('/') ? u : (u + '/')) : '';
      this.username = (username || '').trim();
      this.password = (password || '').trim();
      this.folder = 'JavdbEmbySkin_backup';
    }
    _authHeaders() {
      const h = { 'Depth': '1' };
      if (this.username || this.password) {
        h['Authorization'] = 'Basic ' + btoa(unescape(encodeURIComponent(this.username + ':' + this.password)));
      }
      return h;
    }
    async _request(method, path, headers, data) {
      if (!this.baseUrl) throw new Error('请先填写 WebDAV 服务地址');
      const encodedPath = (path || '').split('/').map(encodeURIComponent).join('/');
      const url = this.baseUrl + encodedPath.replace(/^\//, '');
      const reqHeaders = Object.assign(this._authHeaders(), headers || {});
      return gmHttp.request({ method: method, url: url, headers: reqHeaders, data: data });
    }
    async ensureFolder() {
      if (!this.baseUrl) throw new Error('请先填写 WebDAV 服务地址');
      // 先探测目录是否已存在，避免对已有目录重复调用 MKCOL 产生误报
      try {
        await this._request('PROPFIND', this.folder, { 'Depth': '0' });
        return;
      } catch (_) {}
      try {
        await this._request('MKCOL', this.folder);
      } catch (err) {
        // 405 Method Not Allowed / 409 Conflict 常表示目录已存在，容错放行
        const msg = String(err.message || err);
        if (!msg.includes('405') && !msg.includes('409')) throw err;
      }
    }
    async testConnection() {
      if (!this.baseUrl || !this.username || !this.password) throw new Error('请先填写完整的 WebDAV 服务配置');
      // 简单探测根路径连通性与凭据鉴权
      try {
        await this._request('PROPFIND', '', { 'Depth': '0' });
      } catch (err) {
        const msg = String(err.message || err);
        if (!this.password) throw new Error('请先填写 WebDAV 密码 / 应用授权码');
        if (msg.includes('401') || msg.includes('Unauthorized')) {
          throw new Error('用户名或密码/应用授权码错误 (401 Unauthorized)。坚果云等服务请务必使用“应用授权密码”，不可使用网页登录密码');
        }
        if (msg.includes('403') || msg.includes('Forbidden')) {
          throw new Error('访问被拒绝 (403 Forbidden)，请检查账号对该目录的读写权限');
        }
        if (msg.includes('404')) {
          throw new Error('WebDAV 服务地址不存在 (404)，坚果云请确保地址以 /dav/ 结尾');
        }
        throw err;
      }
      await this.ensureFolder();
      return true;
    }
    async uploadBackup(fileName, jsonString) {
      if (!this.baseUrl || !this.username || !this.password) throw new Error('请先填写完整的 WebDAV 服务配置');
      await this.ensureFolder();
      const path = this.folder + '/' + fileName;
      await this._request('PUT', path, { 'Content-Type': 'application/json; charset=utf-8' }, jsonString);
    }
    async getBackupList() {
      if (!this.baseUrl || !this.username || !this.password) throw new Error('请先填写完整的 WebDAV 服务配置');
      await this.ensureFolder();
      const xml = await this._request('PROPFIND', this.folder, { 'Content-Type': 'application/xml' },
        '<?xml version="1.0"?><d:propfind xmlns:d="DAV:"><d:prop><d:displayname /><d:getcontentlength /><d:getlastmodified /><d:iscollection /></d:prop></d:propfind>');
      const doc = new DOMParser().parseFromString(xml, 'application/xml');
      let responses = [];
      if (typeof doc.getElementsByTagNameNS === 'function') {
        responses = Array.from(doc.getElementsByTagNameNS('*', 'response'));
      }
      if (!responses.length) {
        responses = Array.from(doc.querySelectorAll('response, d\\:response, D\\:response'));
      }
      function findProp(node, tag) {
        if (!node) return null;
        const lower = tag.toLowerCase();
        const el = node.querySelector(tag + ', d\\:' + tag + ', D\\:' + tag);
        if (el) return el;
        const stack = [node];
        while (stack.length) {
          const cur = stack.pop();
          for (let i = 0; i < cur.children.length; i++) {
            const child = cur.children[i];
            const lName = (child.localName || child.nodeName.split(':').pop() || '').toLowerCase();
            if (lName === lower) return child;
            if (child.children.length) stack.push(child);
          }
        }
        return null;
      }
      const list = [];
      responses.forEach(function (r) {
        const hrefNode = findProp(r, 'href');
        const href = hrefNode ? (hrefNode.textContent || '') : '';
        let name = href.split('/').filter(Boolean).pop() || '';
        try { name = decodeURIComponent(name); } catch (_) {}
        const isColNode = findProp(r, 'iscollection') || findProp(r, 'collection');
        const isCol = !!(isColNode && (isColNode.textContent || '').match(/1|true/i)) || (isColNode && isColNode.localName === 'collection');
        if (!name || isCol || !name.endsWith('.json')) return;
        const szNode = findProp(r, 'getcontentlength');
        const sz = parseInt(szNode ? (szNode.textContent || '0') : '0', 10);
        const lmNode = findProp(r, 'getlastmodified');
        const lm = lmNode ? (lmNode.textContent || '') : '';
        list.push({ name: name, size: sz, lastModified: lm });
      });
      list.sort((a, b) => b.name.localeCompare(a.name));
      return list;
    }
    async downloadBackup(fileName) {
      const path = this.folder + '/' + fileName;
      return this._request('GET', path);
    }
    async deleteBackup(fileName) {
      const path = this.folder + '/' + fileName;
      await this._request('DELETE', path);
    }
  }

  /* 云端备份文件查看与恢复弹窗 (WebDAV / Git 通用) */
  function openCloudBackupListModal(files, client, serviceName) {
    let old = document.getElementById('jhs-wd-list-modal');
    if (old) old.remove();
    const modal = document.createElement('div');
    modal.id = 'jhs-wd-list-modal';
    modal.className = 'jhs-settings-mask open';
    modal.style.zIndex = '2147483680';

    const sName = serviceName || '云端';
    let rowsHtml = '';
    if (!files.length) {
      rowsHtml = '<div style="text-align:center;color:#888;padding:30px;">' + sName + ' 暂无历史备份文件</div>';
    } else {
      files.forEach(function (f, i) {
        const sz = f.size ? (f.size > 1048576 ? (f.size / 1048576).toFixed(2) + ' MB' : (f.size / 1024).toFixed(1) + ' KB') : '未知';
        rowsHtml +=
          '<div class="jhs-backup-row" style="display:flex;align-items:center;justify-content:space-between;padding:10px 14px;border-bottom:1px solid rgba(255,255,255,.06);">' +
            '<div>' +
              '<div style="font-size:13px;font-weight:600;color:#fff;">' + escapeHtml(f.name) + '</div>' +
              '<div style="font-size:11px;color:#888;margin-top:2px;">来源: ' + sName + ' · 大小: ' + sz + ((f.lastModified || f.createTime) ? ' · ' + (f.lastModified || f.createTime).slice(0, 19).replace('T', ' ') : '') + '</div>' +
            '</div>' +
            '<div style="display:flex;gap:8px;">' +
              '<button type="button" class="jhs-btn jhs-btn-success btn-wd-restore" data-name="' + escapeAttr(f.name) + '" style="padding:4px 10px;font-size:11.5px;">恢复导入</button>' +
              '<button type="button" class="jhs-btn jhs-btn-secondary btn-wd-dl" data-name="' + escapeAttr(f.name) + '" style="padding:4px 10px;font-size:11.5px;">下载</button>' +
              '<button type="button" class="jhs-btn jhs-btn-danger btn-wd-del" data-name="' + escapeAttr(f.name) + '" data-sha="' + escapeAttr(f.sha || '') + '" style="padding:4px 10px;font-size:11.5px;">删除</button>' +
            '</div>' +
          '</div>';
      });
    }

    modal.innerHTML =
      '<div class="jhs-settings-dialog" style="width:min(680px, 92vw);height:min(500px, 80vh);flex-direction:column;">' +
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:14px 20px;border-bottom:1px solid rgba(255,255,255,.1);">' +
          '<div style="font-size:15px;font-weight:700;color:#fff;"><span class="material-symbols-outlined" style="vertical-align:-3px;">folder_zip</span> ' + sName + ' 备份文件</div>' +
          '<button class="jhs-wd-close material-symbols-outlined" style="background:none;border:none;color:#888;cursor:pointer;font-size:20px;">close</button>' +
        '</div>' +
        '<div style="flex:1;overflow-y:auto;padding:6px 10px;" id="wd-file-container">' + rowsHtml + '</div>' +
      '</div>';

    document.body.appendChild(modal);

    modal.querySelector('.jhs-wd-close').addEventListener('click', () => modal.remove());
    modal.addEventListener('click', e => { if (e.target === modal) modal.remove(); });

    modal.querySelectorAll('.btn-wd-restore').forEach(function (btn) {
      btn.addEventListener('click', async function () {
        const name = btn.getAttribute('data-name');
        if (!confirm('确定将云端备份「' + name + '」导入并覆盖本地数据库吗？')) return;
        btn.textContent = '导入中...';
        try {
          const jsonStr = client.getFileContent ? await client.getFileContent(name) : await client.downloadBackup(name);
          await FAV.importJson(jsonStr);
          alert('云端备份已成功恢复！');
          location.reload();
        } catch (err) {
          alert('恢复失败: ' + err.message);
          btn.textContent = '恢复导入';
        }
      });
    });

    modal.querySelectorAll('.btn-wd-dl').forEach(function (btn) {
      btn.addEventListener('click', async function () {
        const name = btn.getAttribute('data-name');
        btn.textContent = '下载中...';
        try {
          const jsonStr = client.getFileContent ? await client.getFileContent(name) : await client.downloadBackup(name);
          const blob = new Blob([jsonStr], { type: 'application/json;charset=utf-8' });
          const a = document.createElement('a');
          a.href = URL.createObjectURL(blob);
          a.download = name;
          document.body.appendChild(a);
          a.click();
          a.remove();
          setTimeout(function () { URL.revokeObjectURL(a.href); }, 5000);
          btn.textContent = '下载';
        } catch (err) {
          alert('下载失败: ' + err.message);
          btn.textContent = '下载';
        }
      });
    });

    modal.querySelectorAll('.btn-wd-del').forEach(function (btn) {
      btn.addEventListener('click', async function () {
        const name = btn.getAttribute('data-name');
        const sha = btn.getAttribute('data-sha');
        if (!confirm('确定删除云端备份「' + name + '」吗？')) return;
        btn.textContent = '删除中...';
        try {
          if (client.deleteFile) await client.deleteFile(name, sha);
          else await client.deleteBackup(name);
          const row = btn.closest('.jhs-backup-row') || btn.closest('div[style*="justify-content:space-between"]');
          if (row) row.remove();
        } catch (err) {
          alert('删除失败: ' + err.message);
          btn.textContent = '删除';
        }
      });
    });
  }
  const openWebDavListModal = openCloudBackupListModal;

  
  
